    // -------------------------
    // Sensirion Backup - Individual Sensors
    // -------------------------
    sensirion_temp_bottom: get("sensirion_temp_bottom"),
    sensirion_temp_bathroom: get("sensirion_temp_bathroom"),
    sensirion_temp_top: get("sensirion_temp_top"),

    sensirion_hum_bottom: get("sensirion_hum_bottom"),
    sensirion_hum_bathroom: get("sensirion_hum_bathroom"),
    sensirion_hum_top: get("sensirion_hum_top"),

    sensirion_co2_top: get("sensirion_co2_top"),

    // -------------------------
    // Sensirion Backup - Aggregated
    // -------------------------
    sensirion_temperature: get("sensirion_temperature"),
    sensirion_humidity: get("sensirion_humidity"),
    sensirion_co2: get("sensirion_co2"),
    sensirion_last_update: get("sensirion_last_update"),

    // -------------------------
    // Energy
    // -------------------------
    solar_power: get("solar_power", 0),
    solar_power_trend: get("solar_power_trend"),
    solar_power_last_update: get("solar_power_last_update"),

    grid_power: get("grid_power", 0),
    grid_power_trend: get("grid_power_trend"),
    grid_power_last_update: get("grid_power_last_update"),

    battery_soc: get("battery_soc", 0),

    // -------------------------
    // Motion + Lux (Main)
    // -------------------------
    motion: get("motion", false),
    last_motion: get("last_motion"),
    lux: get("lux"),

    // -------------------------
    // Motion + Lux (Bad)
    // -------------------------
    motion_bad: get("motion_bad", false),
    last_motion_bad: get("last_motion_bad"),
    lux_bad: get("lux_bad")
};


// ------------------------------------------------
// Derived Diagnostics
// ------------------------------------------------

if (snapshot.last_motion) {
    snapshot.seconds_since_motion =
        nowSec - snapshot.last_motion;
}

if (snapshot.last_motion_bad) {
    snapshot.seconds_since_motion_bad =
        nowSec - snapshot.last_motion_bad;
}

if (snapshot.solar_power_last_update) {
    snapshot.seconds_since_solar_update =
        Math.floor((nowMs - snapshot.solar_power_last_update) / 1000);
}

if (snapshot.grid_power_last_update) {
    snapshot.seconds_since_grid_update =
        Math.floor((nowMs - snapshot.grid_power_last_update) / 1000);
}

if (snapshot.sensirion_last_update) {
    snapshot.seconds_since_sensirion_update =
        Math.floor((nowMs - snapshot.sensirion_last_update) / 1000);
}


// ------------------------------------------------
// Output
// ------------------------------------------------

msg.payload = snapshot;
return msg;

// ------------------------------------------------
// SENSIRION BACKUP STORAGE + MEAN AGGREGATION
// Connect ALL backup MQTT topics here
// ------------------------------------------------

// Validate payload
let value = Number(msg.payload);
if (!Number.isFinite(value)) {
    return null; // ignore null / NaN
}

let topic = msg.topic || "";

// ------------------------------------------------
// Store individual sensor values
// ------------------------------------------------

function store(key, val) {
    flow.set(key, val);
}

// Temperature sensors
if (topic === "energiemonitor/humi/bottom/temperature") {
    store("sensirion_temp_bottom", value);
}
else if (topic === "energiemonitor/humi/bathroom/temperature") {
    store("sensirion_temp_bathroom", value);
}
else if (topic === "energiemonitor/aiq/top/temperature") {
    store("sensirion_temp_top", value);
}

// Humidity sensors
else if (topic === "energiemonitor/humi/bottom/humidity") {
    store("sensirion_hum_bottom", value);
}
else if (topic === "energiemonitor/humi/bathroom/humidity") {
    store("sensirion_hum_bathroom", value);
}
else if (topic === "energiemonitor/aiq/top/humidity") {
    store("sensirion_hum_top", value);
}

// CO2 sensor
else if (topic === "energiemonitor/co2/top/co2") {
    store("sensirion_co2_top", value);
}

else {
    return null; // ignore unrelated topics
}


// ------------------------------------------------
// Helper: calculate mean of valid numbers
// ------------------------------------------------

function mean(values) {
    let valid = values.filter(v => Number.isFinite(v));
    if (valid.length === 0) return null;
    return valid.reduce((a, b) => a + b, 0) / valid.length;
}


// ------------------------------------------------
// Calculate aggregated backup values
// ------------------------------------------------

// Temperature mean (3 sensors max)
let tempMean = mean([
    flow.get("sensirion_temp_bottom"),
    flow.get("sensirion_temp_bathroom"),
    flow.get("sensirion_temp_top")
]);

// Humidity mean (3 sensors max)
let humMean = mean([
    flow.get("sensirion_hum_bottom"),
    flow.get("sensirion_hum_bathroom"),
    flow.get("sensirion_hum_top")
]);

// CO2 mean (currently 1 sensor, future-proofed)
let co2Mean = mean([
    flow.get("sensirion_co2_top")
]);


// ------------------------------------------------
// Store aggregated backup values
// ------------------------------------------------

if (tempMean !== null)
    flow.set("sensirion_temperature", tempMean);

if (humMean !== null)
    flow.set("sensirion_humidity", humMean);

if (co2Mean !== null)
    flow.set("sensirion_co2", co2Mean);


// Optional: store last update timestamp
flow.set("sensirion_last_update", Date.now());


// No output needed (pure storage node)
return null;

// Ensure payload exists and contains a numeric value
if (msg.payload && typeof msg.payload.value === "number") {

    const soc = msg.payload.value;

    // Store SOC in flow context
    flow.set("battery_soc", soc);

    // Optional: also attach to msg for downstream debugging
    msg.battery_soc = soc;

    return msg;
}

// If invalid message, do nothing
return null;
